CREATE TABLE "proposal_deliveries" ("id" TEXT NOT NULL PRIMARY KEY,"proposalId" TEXT NOT NULL,"requestKey" TEXT NOT NULL,"invitationId" TEXT NOT NULL,"recipient" TEXT NOT NULL,"subject" TEXT NOT NULL,"text" TEXT NOT NULL,"snapshotHash" TEXT NOT NULL,"pdfHash" TEXT NOT NULL,"pdf" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'SENDING',"messageId" TEXT,"errorCode" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" DATETIME,CONSTRAINT "proposal_deliveries_proposalId_fkey" FOREIGN KEY("proposalId") REFERENCES "case_proposals"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "proposal_deliveries_proposalId_requestKey_key" ON "proposal_deliveries"("proposalId","requestKey");
CREATE INDEX "proposal_deliveries_proposalId_createdAt_idx" ON "proposal_deliveries"("proposalId","createdAt");
